INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Mockdaten immer zufällig generiert?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch festgelegt sein"}, {"text": "Ja", "correct": false, "because": "Kontrolle ist oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich in Python für realistische Mockdaten?', 3, '[{"text": "Faker", "correct": true, "because": "Erzeugt glaubwürdige Daten"}, {"text": "Random", "correct": false, "because": "Nur Zufallszahlen"}, {"text": "Pandas", "correct": false, "because": "Für Datenanalyse, nicht Generierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Mockdaten für Tests nützlich?', 5, '[{"text": "Realitätsnähe", "correct": true, "because": "Simuliert echte Szenarien"}, {"text": "Vielfalt", "correct": true, "because": "Testet verschiedene Fälle"}, {"text": "Kleine Datenmenge", "correct": false, "because": "Menge kann variieren"}, {"text": "Statische Werte", "correct": false, "because": "Dynamik ist oft besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Mockdaten müssen echte Daten nachahmen. b) Sie dürfen nie echt sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Echte Daten können enthalten sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Mockdaten für eine Datenbank-Demo?', 4, '[{"text": "Datenintegrität", "correct": false, "because": "Wichtig für Glaubwürdigkeit"}, {"text": "Relevante Felder", "correct": false, "because": "Müssen zum Schema passen"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Mockdaten auch für UI-Tests geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Sie simulieren Inhalte"}, {"text": "Nein", "correct": false, "because": "UI braucht oft Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Mockdaten wähle ich für eine Kundendatenbank?', 3, '[{"text": "Namen und Adressen", "correct": true, "because": "Typisch für Kunden"}, {"text": "Zufällige Binärdaten", "correct": false, "because": "Unrealistisch"}, {"text": "Farbcodes", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze helfen bei der Erstellung von Mockdaten?', 5, '[{"text": "Bibliotheken wie Faker", "correct": true, "because": "Automatisiert realistische Daten"}, {"text": "Manuelle Eingabe", "correct": true, "because": "Präzise Kontrolle"}, {"text": "Kopieren echter Daten", "correct": false, "because": "Datenschutzrisiko"}, {"text": "Leer lassen", "correct": false, "because": "Nutzenlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Mockdaten sollten echt wirken. b) Sie müssen immer zufällig sein. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zufall ist optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Mockdaten in einem Test?', 4, '[{"text": "Konsistenz", "correct": false, "because": "Wichtig für Glaubwürdigkeit"}, {"text": "Realismus", "correct": false, "because": "Simuliert echte Fälle"}, {"text": "Grafische Darstellung", "correct": true, "because": "Nur Daten zählen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Mockdaten nur für Entwickler nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Demos und QA"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten eignen sich für eine Verkaufsdemo?', 4, '[{"text": "Produktnamen und Preise", "correct": true, "because": "Realistisch für Verkauf"}, {"text": "Zufällige Zeichen", "correct": false, "because": "Unbrauchbar"}, {"text": "Leere Felder", "correct": false, "because": "Kein Mehrwert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Mockdaten immer echt sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sie simulieren, sind aber nicht echt"}, {"text": "Ja", "correct": false, "because": "Echte Daten sind optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Mockdaten für einen API-Test?', 3, '[{"text": "Strukturkompatibilität", "correct": true, "because": "Muss zur API passen"}, {"text": "Schnelle Generierung", "correct": false, "because": "Sekundär"}, {"text": "Visuelle Schönheit", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mockdaten testen Edge-Cases. b) Sie müssen immer vollständig sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vollständigkeit ist optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen Mockdaten-Generierung?', 5, '[{"text": "Faker", "correct": true, "because": "Realistische Daten"}, {"text": "Mockaroo", "correct": true, "because": "Online-Datengenerator"}, {"text": "Excel", "correct": false, "because": "Manuell, kein Generator"}, {"text": "Photoshop", "correct": false, "because": "Für Bilder, nicht Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Mockdaten für eine Präsentation?', 3, '[{"text": "Lesbarkeit", "correct": false, "because": "Wichtig für Zuschauer"}, {"text": "Relevanz", "correct": false, "because": "Muss zum Thema passen"}, {"text": "Hardware-Spezifikationen", "correct": true, "because": "Irrelevant für Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit Mockdaten? Müssen sie immer groß sein?', 3, '[{"text": "Nein", "correct": true, "because": "Größe hängt vom Zweck ab"}, {"text": "Ja", "correct": false, "because": "Kleine Sets reichen oft"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Mockdaten auch Fehler simulieren sollten?', 2, '[{"text": "Ja", "correct": true, "because": "Gut für Robustheitstests"}, {"text": "Nein", "correct": false, "because": "Fehler sind oft nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten wähle ich für eine Benutzerdemo?', 4, '[{"text": "Namen und E-Mails", "correct": true, "because": "Realistisch für Benutzer"}, {"text": "Zufällige Zahlen", "correct": false, "because": "Unbrauchbar"}, {"text": "Leerzeichen", "correct": false, "because": "Kein Nutzen"}]');
